import { readFileSync } from 'node:fs'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

function changes(base, side, who) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const out = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) out.push({ bs, be: i, ss, se: j, who })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush()
      i++; j++; bs = i; ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return out
}

const args = process.argv.slice(2)
if (args.length !== 1 || !['merge', 'merge2', 'regions'].includes(args[0])) fail('error: usage: cli.js merge|merge2|regions')
const mode = args[0]

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()
const docs = [[]]
for (const l of lines) {
  if (l === '%%%') docs.push([])
  else docs[docs.length - 1].push(l)
}
if (docs.length !== 3) fail('error: expected three parts separated by %%%')
const [mine, base, theirs] = docs

const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
all.sort((a, b) => a.bs - b.bs || a.who - b.who)

const same = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])
const items = [] // {kind, lines, base, mine, theirs}
let pos = 0
let k = 0
while (k < all.length) {
  const rs = all[k].bs
  let re = all[k].be
  const group = [all[k++]]
  while (k < all.length && all[k].bs <= re) {
    re = Math.max(re, all[k].be)
    group.push(all[k++])
  }
  if (rs > pos) items.push({ kind: 'stable', lines: base.slice(pos, rs) })
  pos = re
  if (group.length === 1) {
    const c = group[0]
    const lines = (c.who === 0 ? mine : theirs).slice(c.ss, c.se)
    items.push({ kind: c.who === 0 ? 'mine' : 'theirs', lines })
    continue
  }
  const baseL = base.slice(rs, re)
  const side = (who, doc) => {
    const g = group.filter(c => c.who === who)
    if (!g.length) return baseL
    const s0 = Math.min(...g.map(c => c.bs)), e0 = Math.max(...g.map(c => c.be))
    const ss = Math.min(...g.map(c => c.ss)) - (s0 - rs)
    const se = Math.max(...g.map(c => c.se)) + (re - e0)
    return doc.slice(ss, se)
  }
  const ml = side(0, mine), tl = side(1, theirs)
  if (same(ml, tl)) items.push({ kind: 'both', lines: ml })
  else if (same(ml, baseL)) items.push({ kind: 'theirs', lines: tl })
  else if (same(tl, baseL)) items.push({ kind: 'mine', lines: ml })
  else items.push({ kind: 'conflict', base: baseL, mine: ml, theirs: tl })
}
if (pos < base.length) items.push({ kind: 'stable', lines: base.slice(pos) })

const out = []
let conflict = false
for (const it of items) {
  if (it.kind === 'conflict') conflict = true
  if (mode === 'regions') {
    out.push(it.kind === 'conflict'
      ? `conflict mine=${it.mine.length} base=${it.base.length} theirs=${it.theirs.length}`
      : `${it.kind} ${it.lines.length}`)
  } else if (it.kind === 'conflict') {
    out.push('<<<<<<< mine', ...it.mine)
    if (mode === 'merge') out.push('||||||| base', ...it.base)
    out.push('=======', ...it.theirs, '>>>>>>> theirs')
  } else out.push(...it.lines)
}
process.stdout.write(out.map(l => l + '\n').join(''))
process.exitCode = conflict ? 1 : 0
